#include "../Source/HarmonicDSP.h"
#include <cmath>
#include <cstdlib>
#include <iostream>
#include <random>
#include <vector>
static void check(bool v,const char*n){if(!v){std::cerr<<"FAIL: "<<n<<'\n';std::exit(1);}}static double projection(const std::vector<float>&x,double f,double sr,size_t begin){double s=0,c=0;for(size_t n=begin;n<x.size();++n){double p=2*3.14159265358979323846*f*n/sr;s+=x[n]*std::sin(p);c+=x[n]*std::cos(p);}return 2*std::sqrt(s*s+c*c)/(x.size()-begin);}static double harmonicLevel(double f,int h,float color){constexpr double sr=96000;cloudy::Engine e;e.prepare(sr);e.configure(100,color,0,h);std::vector<float>out(96000);for(size_t n=0;n<out.size();++n){float x=float(.5*std::sin(2*3.14159265358979323846*f*n/sr));out[n]=e.process({x,x})[0];}return projection(out,f*h,sr,24000);}int main(){constexpr double sr=48000;{cloudy::Engine e;e.prepare(sr);e.configure(0,0,0,9);std::mt19937 r(9);std::uniform_real_distribution<float>d(-.8f,.8f);for(int n=0;n<20000;++n){float x=d(r);auto y=e.process({x,-x});check(std::abs(y[0]-x)<1e-6f&&std::abs(y[1]+x)<1e-6f,"zero amount transparent");}}{cloudy::Engine e;e.prepare(sr);e.configure(100,0,0,9);for(int n=0;n<50000;++n){auto y=e.process({n?0.f:1.f,n?0.f:1.f});check(std::isfinite(y[0]),"finite output");}}check(harmonicLevel(300,9,0)>.015&&harmonicLevel(300,8,0)>.015,"debug harmonic selection");check(harmonicLevel(100,9,-100)>harmonicLevel(100,9,100)*1.15,"negative color favors lows");check(harmonicLevel(3000,9,100)>harmonicLevel(3000,9,-100)*1.15,"positive color favors highs");{cloudy::Engine e;e.prepare(sr);e.configure(100,0,0,9);for(int n=0;n<2000;++n){float x=float(.4*std::sin(2*3.14159265358979323846*440*n/sr));auto y=e.process({x,x},true);check(y[0]==x,"exact bypass");}}std::cout<<"PASS Cloudy9 DSP\n";}
